import{_ as t,o,c as s,a2 as a}from"./chunks/framework.CjPXnAcb.js";const u=JSON.parse('{"title":"Python 环境与 pip —— 把工具箱整理好","description":"","frontmatter":{"title":"Python 环境与 pip —— 把工具箱整理好"},"headers":[],"relativePath":"prereq/06-python-env.md","filePath":"prereq/06-python-env.md","lastUpdated":1789060104000}'),p={name:"prereq/06-python-env.md"};function i(n,e,d,c,l,r){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="_06-·-python-环境与-pip-开工前的最后一步" tabindex="-1">06 · Python 环境与 pip：开工前的最后一步 <a class="header-anchor" href="#_06-·-python-环境与-pip-开工前的最后一步" aria-label="Permalink to &quot;06 · Python 环境与 pip：开工前的最后一步&quot;">​</a></h1><blockquote><p>一句话说清这课解决什么问题：搞懂 Python 代码是怎么被电脑执行的、<code>pip install</code> 到底把东西装到了哪、以及为什么以后每个项目要一个独立「书架」。</p></blockquote><h2 id="它是什么-大白话-生活比喻" tabindex="-1">它是什么？（大白话 + 生活比喻） <a class="header-anchor" href="#它是什么-大白话-生活比喻" aria-label="Permalink to &quot;它是什么？（大白话 + 生活比喻）&quot;">​</a></h2><p>先想一个问题：电脑只认识 0 和 1，你写的 <code>print(&quot;hello&quot;)</code> 它凭什么懂？靠<strong>解释器</strong>（interpreter）——一个把 Python 代码「同声传译」成机器指令的程序。你每跑一次 <code>.py</code> 文件，都是解释器现场读一行、翻一行、执行一行。</p><p>你机器上的这位翻译官叫 <code>py</code>（Windows 的 py 启动器，帮你找到装好的 Python 3.14.4，和直接敲 <code>python</code> 效果基本一样，一句话带过：<code>py</code> 更保险，不怕 PATH 里指错人）。</p><p>但是翻译官只自带基础词汇。想要新能力（比如发 HTTP 请求），就得装<strong>包</strong>（package，别人写好的一套代码，拿来即用）。负责装包的快递员叫 <strong>pip</strong>——Python 世界的应用商店配送员，对应前端世界的 npm。</p><p><code>py -m pip install 包名</code> 这条命令背后是三步：</p><ol><li>去官方仓库 PyPI（一个存着几十万个包的大仓库）找这本书；</li><li>下载下来；</li><li>装进本机的 <code>site-packages</code>——你可以理解为翻译官家的<strong>书架</strong>，以后 <code>import</code> 就是去书架上取书。</li></ol><h2 id="为什么我们需要它" tabindex="-1">为什么我们需要它？ <a class="header-anchor" href="#为什么我们需要它" aria-label="Permalink to &quot;为什么我们需要它？&quot;">​</a></h2><p>你的项目清单全靠它：</p><ul><li>调智谱 GLM 的 API 要装 <code>openai</code> 或 <code>zhipuai</code> 包；</li><li>本课和上一课的例子已经用了 <code>requests</code> 包；</li><li>以后做网页服务、读文件、跑 agent，全是装包 → <code>import</code> → 干活。</li></ul><p>还有一个提前打预防针的概念：<strong>依赖</strong>（dependency，你的项目运行所需要的那些包）。项目 A 依赖 1.0 版的某包、项目 B 依赖 2.0 版，全挤在一个书架上就会打架。解法是 <strong>venv（虚拟环境）</strong>：给每个项目一个独立书架，互不干扰。阶段 3 会带你亲手建，本课只需要记住这个比喻。</p><p>先扎实把本课的事做完：确认翻译官在岗、快递员在岗、能装包、装完能验证。</p><h2 id="动手试一试" tabindex="-1">动手试一试 <a class="header-anchor" href="#动手试一试" aria-label="Permalink to &quot;动手试一试&quot;">​</a></h2><p>打开 cmd（按 <code>Win+R</code>，输 <code>cmd</code>，回车），依次敲下面四条命令：</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">py --version</span></span></code></pre></div><p>这条命令在干什么：让翻译官自报版本号，期待输出 <code>Python 3.14.4</code>，确认它装好且在岗。</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">py -m pip --version</span></span></code></pre></div><p>这条命令在干什么：确认快递员在岗，期待输出 <code>pip 26.0.1 ...</code>。<code>-m pip</code> 的意思是「用刚才那个翻译官（py）自带的 pip 模块」，而不是随便从 PATH 里抓一个来路不明的 pip。</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">py -m pip install requests</span></span></code></pre></div><p>这条命令在干什么：走完「找书 → 下载 → 上架」三步，把 requests 包装进 site-packages 书架。看到一行行 <code>Downloading</code> / <code>Installing</code> 最后 <code>Successfully installed</code> 就是成功。</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">py -c </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;import requests; print(requests.__version__)&quot;</span></span></code></pre></div><p>这条命令在干什么：<code>-c</code> 表示直接执行一句代码——去书架取 requests 这本书，打印它的版本号。能打印出版本号，说明这本书确实装上了、取得到。这是「装完必验证」的好习惯。</p><p><strong>为什么要写成 <code>py -m pip</code> 而不是光秃秃的 <code>pip</code>？</strong> 光敲 <code>pip</code> 时，Windows 会去 PATH（系统找程序的搜索清单）里翻，可能翻到另一个 Python 的 pip——结果包装进了别人的书架，你 <code>import</code> 时却取不到。<code>py -m pip</code> 把「翻译官」和「快递员」绑死成同一个人，从根上避开这个坑。</p><h3 id="预告-装得慢怎么办——镜像" tabindex="-1">预告：装得慢怎么办——镜像 <a class="header-anchor" href="#预告-装得慢怎么办——镜像" aria-label="Permalink to &quot;预告：装得慢怎么办——镜像&quot;">​</a></h3><p>PyPI 的服务器在国外，国内下载可能龟速。<strong>镜像</strong>（mirror，仓库的国内分店）能救急，用清华源：</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">py -m pip install 包名 -i https://pypi.tuna.tsinghua.edu.cn/simple</span></span></code></pre></div><p>这条命令在干什么：<code>-i</code> 指定「去清华这家分店进货」，货是一样的，只是近得多。</p><h2 id="常见报错与怎么读它" tabindex="-1">常见报错与怎么读它 <a class="header-anchor" href="#常见报错与怎么读它" aria-label="Permalink to &quot;常见报错与怎么读它&quot;">​</a></h2><p>最经典的报错，你在 cmd 里跑一句 <code>import requests</code> 时可能见到：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Traceback (most recent call last):</span></span>
<span class="line"><span>  File &quot;&lt;stdin&gt;&quot;, line 1, in &lt;module&gt;</span></span>
<span class="line"><span>ModuleNotFoundError: No module named &#39;requests&#39;</span></span></code></pre></div><p>怎么读报错（这是你人生必会技能，Python 报错叫 traceback，从下往上读）：</p><ol><li><strong>最后一行是结论</strong>：<code>ModuleNotFoundError: No module named &#39;requests&#39;</code>——书架上没这本书。前面几行是「案发经过」（在哪个文件哪一行摔倒的），初学先只看最后一行。</li><li><strong>两种可能</strong>：a) 根本没装过；b) 装了，但<strong>装到别的书架去了</strong>——比如你曾用光秃秃的 <code>pip install</code> 装到了另一个 Python 的 site-packages，而现在 <code>py</code> 用的是这个书架。</li></ol><p>解决办法按顺序试：</p><ul><li>没装过 → <code>py -m pip install requests</code> 装上；</li><li>装过还报错 → 用 <code>py -m pip show requests</code> 查这本书装到了哪、再重新用 <code>py -m pip install requests</code> 装进正确的书架；</li><li>装完<strong>必跑验证命令</strong>：<code>py -c &quot;import requests; print(requests.__version__)&quot;</code>，打印出版本才算数，不要凭「刚才装过了」想当然。</li></ul><h2 id="自测两题" tabindex="-1">自测两题 <a class="header-anchor" href="#自测两题" aria-label="Permalink to &quot;自测两题&quot;">​</a></h2><p><strong>第 1 题</strong>：<code>py -m pip install requests</code> 成功了，但运行 <code>import requests</code> 仍然报 <code>ModuleNotFoundError</code>，最可能的原因是什么？</p><details class="details custom-block"><summary>点击看答案</summary><p>包装进了「别的书架」：当年用的是不带 <code>py -m</code> 的 <code>pip</code>，它属于另一个 Python，装进了另一个解释器的 site-packages。而 <code>py</code> 启动的翻译官去自己的书架上找，当然找不到。解法：统一改用 <code>py -m pip install requests</code>，让翻译官和快递员是同一个人。</p></details><p><strong>第 2 题</strong>：<code>pip install</code> 下载特别慢甚至超时，一条命令怎么解决？</p><details class="details custom-block"><summary>点击看答案</summary><p>换国内镜像源，比如清华源：<code>py -m pip install 包名 -i https://pypi.tuna.tsinghua.edu.cn/simple</code>。<code>-i</code> 的意思是去指定的镜像分店下载，包的内容完全一样，只是服务器在国内、速度快得多。</p></details><h2 id="下一课" tabindex="-1">下一课 <a class="header-anchor" href="#下一课" aria-label="Permalink to &quot;下一课&quot;">​</a></h2><p>到此你的三件套齐了：会写 Markdown（网站的内容）、懂 HTTP 与 API（和 AI 对话的规则）、环境与 pip（工具箱就位）。下一阶段开始，你就要亲手写出第一段调用智谱 GLM 的 Python 代码，让你自己的 Wiki 项目真正「长出大脑」。</p>`,42)])])}const g=t(p,[["render",i]]);export{u as __pageData,g as default};
